package com.acgreader.mobile;
import java.io.*;import java.nio.file.*;
public class AnimationCacheTest {public static void main(String[] args)throws Exception{File source=new File("build/sample-animation.bin");ImageFormatInfo info=ImageFormatInfo.inspect(source);if(!info.mime.equals("image/gif")||info.frames!=157)throw new AssertionError("animation metadata");File copy=new File("build/animation-copy.gif");try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(copy)){AlbumSaver.copy(in,out);}if(Files.mismatch(source.toPath(),copy.toPath())!=-1)throw new AssertionError("original bytes changed");LocalGateway g=new LocalGateway(null,new File("build/native-cache-test"));try{StringBuilder hash=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest("https://m.acgnfl.com/24/08/content_53/534197.gif".getBytes("UTF-8")))hash.append(String.format("%02x",value));File seed=new File("build/native-cache-test/media-originals",hash.toString());seed.getParentFile().mkdirs();Files.copy(source.toPath(),seed.toPath(),StandardCopyOption.REPLACE_EXISTING);File first=g.imageFile("https://m.acgnfl.com/24/08/content_53/534197.gif",true);long start=System.nanoTime();File second=g.imageFile("https://m.acgnfl.com/24/08/content_53/534197.gif",true);if(!first.equals(second)||Files.mismatch(source.toPath(),first.toPath())!=-1)throw new AssertionError("cache bytes");System.out.println("GIF: "+info.frames+" frames; original copy matches; cached read "+((System.nanoTime()-start)/1000000)+" ms");}finally{g.cache.close();g.cancelAll();}}}
